static int failures;
#define CHECK(x) do { if(!(x)){fprintf(stderr,"visual line%d: %s\n",__LINE__,#x);++failures;} } while(0)
static void pump(DWORD ms)
{ULONGLONG end=GetTickCount64()+ms;do{MSG m;unsigned n=0;while(n++<1000&&PeekMessageW(&m,NULL,0,0,PM_REMOVE))if(m.message!=WM_QUIT){TranslateMessage(&m);DispatchMessageW(&m);}Sleep(1);}while(GetTickCount64()<end);}
static ui_status_t presentation(ui_component_t *c,const char *id,ui_element_presentation_t *p)
{ULONGLONG end=GetTickCount64()+10000;ui_status_t status;do{status=ui_component_get_presentation(c,id,p);if(status!=UI_STATUS_PENDING)return status;pump(1);}while(GetTickCount64()<end);return status;}
static int press(ui_web_view_t *v,const char *id)
{ui_element_presentation_t p={0};ui_input_event_t e={0};p.size=sizeof(p);if(ui_web_view_get_presentation(v,id,&p)!=UI_STATUS_OK||!p.visible||!p.enabled)return 0;e.size=sizeof(e);e.pointer_button=1;e.x=p.clip.x+p.clip.width/2;e.y=p.clip.y+p.clip.height/2;e.kind=UI_INPUT_POINTER_DOWN;if(ui_web_view_dispatch_input(v,&e)!=UI_STATUS_OK)return 0;e.kind=UI_INPUT_POINTER_UP;return ui_web_view_dispatch_input(v,&e)==UI_STATUS_OK;}

static int component_press(ui_component_t *c,const char *id)
{ui_element_presentation_t p={0};ui_input_event_t e={0};p.size=sizeof(p);if(presentation(c,id,&p)!=UI_STATUS_OK||!p.visible||!p.enabled)return 0;e.size=sizeof(e);e.pointer_button=1;e.x=p.clip.x+p.clip.width/2;e.y=p.clip.y+p.clip.height/2;e.kind=UI_INPUT_POINTER_DOWN;if(ui_component_dispatch_input(c,&e)!=UI_STATUS_OK)return 0;pump(20);e.kind=UI_INPUT_POINTER_UP;if(ui_component_dispatch_input(c,&e)!=UI_STATUS_OK)return 0;pump(30);return 1;}
static void save_bmp(const wchar_t *prefix,const wchar_t *name,const void *bits,int width,int height)
{wchar_t path[4096];FILE *f=NULL;BITMAPFILEHEADER file={0};BITMAPINFOHEADER info={0};if(!prefix)return;swprintf(path,4096,L"%s-%s.bmp",prefix,name);file.bfType=0x4d42;file.bfOffBits=sizeof(file)+sizeof(info);file.bfSize=file.bfOffBits+(DWORD)width*(DWORD)height*4;info.biSize=sizeof(info);info.biWidth=width;info.biHeight=-height;info.biPlanes=1;info.biBitCount=32;CHECK(!_wfopen_s(&f,path,L"wb"));if(f){CHECK(fwrite(&file,sizeof(file),1,f)==1);CHECK(fwrite(&info,sizeof(info),1,f)==1);CHECK(fwrite(bits,4,(size_t)width*height,f)==(size_t)width*height);fclose(f);}}
static void host_frame(HWND hwnd,const wchar_t *prefix,const wchar_t *name)
{RECT r;HDC dc;HBITMAP bmp;HGDIOBJ old;BITMAPINFO info={0};void *bits;GetWindowRect(hwnd,&r);r.right-=r.left;r.bottom-=r.top;dc=CreateCompatibleDC(NULL);info.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);info.bmiHeader.biWidth=r.right;info.bmiHeader.biHeight=-r.bottom;info.bmiHeader.biPlanes=1;info.bmiHeader.biBitCount=32;bmp=CreateDIBSection(dc,&info,DIB_RGB_COLORS,&bits,NULL,0);CHECK(bmp!=NULL);if(bmp){old=SelectObject(dc,bmp);CHECK(PrintWindow(hwnd,dc,2));GdiFlush();save_bmp(prefix,name,bits,r.right,r.bottom);SelectObject(dc,old);DeleteObject(bmp);}DeleteDC(dc);}
static unsigned background(ui_component_t *c,const wchar_t *prefix,const wchar_t *name,uint32_t dpi,int height)
{ui_pixel_buffer_t p={0};ui_status_t status;ULONGLONG end;unsigned color=0;p.size=sizeof(p);CHECK(ui_component_capture_rgba(c,480,height,dpi,&p)==UI_STATUS_OK);p.capacity=p.stride*p.height;p.pixels=(uint8_t *)malloc(p.capacity);CHECK(p.pixels!=NULL);if(!p.pixels)return 0;end=GetTickCount64()+10000;do{status=ui_component_capture_rgba(c,480,height,dpi,&p);if(status!=UI_STATUS_PENDING)break;pump(1);}while(GetTickCount64()<end);CHECK(status==UI_STATUS_OK);if(status==UI_STATUS_OK){size_t at=p.stride*2+2*4;color=((unsigned)p.pixels[at]<<16)|((unsigned)p.pixels[at+1]<<8)|p.pixels[at+2];for(size_t i=0;i<p.capacity;i+=4){uint8_t red=p.pixels[i];p.pixels[i]=p.pixels[i+2];p.pixels[i+2]=red;}save_bmp(prefix,name,p.pixels,p.width,p.height);}free(p.pixels);return color;}
static unsigned pixel(ui_web_view_t *v,int x,int y)
{ui_pixel_buffer_t p={0};unsigned color=0;p.size=sizeof(p);CHECK(ui_web_view_capture_rgba(v,160,100,96,&p)==UI_STATUS_OK);p.capacity=p.stride*p.height;p.pixels=malloc(p.capacity);CHECK(p.pixels!=NULL);if(p.pixels){CHECK(ui_web_view_capture_rgba(v,160,100,96,&p)==UI_STATUS_OK);size_t at=p.stride*(size_t)y+(size_t)x*4;color=((unsigned)p.pixels[at]<<16)|((unsigned)p.pixels[at+1]<<8)|p.pixels[at+2];free(p.pixels);}return color;}
