{ui_light_web_config_t config={sizeof(config)};ui_web_backend_t *backend=ui_light_web_backend_create(&config);ui_web_view_t *v=ui_web_view_create(h,backend);ui_input_event_t e={0};
 CHECK(v!=NULL);if(!v)return;CHECK(ui_web_view_load_html(v,"<style>body{margin:0;background:#ffffff}#cell{height:30px;width:100px;border:1px solid #dddddd}button{height:30px;width:100px;border:0;background:#ffffff}button:active{background:#123456}</style><body><div id='cell'>Visible cell</div><button id='press'>Action</button><div class='glyph' style='font-family:Segoe MDL2 Assets'>\xEE\x9C\x8D</div></body>")==UI_STATUS_OK);
 CHECK(pixel(v,80,15)==0xffffff);e.size=sizeof(e);e.pointer_button=1;e.x=80;e.y=45;e.kind=UI_INPUT_POINTER_DOWN;CHECK(ui_web_view_dispatch_input(v,&e)==UI_STATUS_OK);CHECK(pixel(v,80,45)==0x123456);e.kind=UI_INPUT_CANCEL;CHECK(ui_web_view_dispatch_input(v,&e)==UI_STATUS_OK);CHECK(pixel(v,80,45)==0xffffff);ui_web_view_destroy(v);ui_light_web_backend_destroy(backend);}

static void polish_geometry(ui_component_t *table,ui_component_t *form,ui_component_t *viewport)
{ui_element_presentation_t label={0},input={0},image={0},title={0},header={0},cell={0};label.size=input.size=image.size=title.size=header.size=cell.size=sizeof(label);
 CHECK(presentation(form,"title",&title)==UI_STATUS_OK&&!title.visible);
 CHECK(presentation(form,"label-name",&label)==UI_STATUS_OK&&label.visible);CHECK(presentation(form,"field-name",&input)==UI_STATUS_OK&&input.visible);
 CHECK(label.clip.width>=72&&input.clip.width>=100&&abs(label.rect.y-input.rect.y)<=1&&input.rect.x>=label.rect.x+label.rect.width);
 CHECK(presentation(viewport,"controls",&title)==UI_STATUS_OK&&!title.visible);CHECK(presentation(viewport,"preview-pixels",&image)==UI_STATUS_OK&&image.visible&&image.clip.width>=120&&image.clip.height==image.clip.width);
 CHECK(presentation(table,"sort-name",&header)==UI_STATUS_OK);CHECK(presentation(table,"cell-9007199254741000-name",&cell)==UI_STATUS_OK);printf("Header/content: %d,%d versus %d,%d\n",header.rect.x,header.rect.width,cell.rect.x,cell.rect.width);CHECK(header.rect.x==cell.rect.x&&header.rect.width==cell.rect.width);
}
